import { readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { describe, expect, it } from 'vitest';

import { InvalidPasswordError } from '../../src/crypto/errors';
import { AccountInformation } from '../../src/format/account';
import { DatabaseOptions } from '../../src/format/options';
import { PasswordDatabase } from '../../src/format/passwordDatabase';
import { toHex } from '../helpers/bytes';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..');
const dbBytes = new Uint8Array(readFileSync(resolve(root, 'scripts/test.db')));
const password = readFileSync(resolve(root, 'scripts/test.db.password'), 'utf8').trim();

function loadFixture(): Promise<PasswordDatabase> {
  return PasswordDatabase.load(dbBytes, password);
}

describe('PasswordDatabase.load', () => {
  it('loads test.db: revision 2, empty options, one known account', async () => {
    const db = await loadFixture();
    expect(db.getRevision()).toBe(2);
    expect(db.getVersion()).toBe(3);
    expect(db.getDbOptions().remoteLocation).toBe('');
    expect(db.getDbOptions().authDBEntry).toBe('');

    const accounts = db.getAccounts();
    expect(accounts).toHaveLength(1);
    expect(accounts[0]).toMatchObject({
      accountName: 'test',
      userId: 'test',
      password: 'bYxwbP1r',
      url: '',
      notes: 'test',
    });
  });

  it('throws InvalidPasswordError for a wrong password', async () => {
    await expect(PasswordDatabase.load(dbBytes, 'nope')).rejects.toBeInstanceOf(
      InvalidPasswordError,
    );
  });

  it('loads a v2 database and upgrades it to v3 on save', async () => {
    const v2 = dbBytes.slice();
    v2[3] = 0x02;
    const db = await PasswordDatabase.load(v2, password);
    expect(db.getVersion()).toBe(2);
    expect(db.getAccount('test')?.password).toBe('bYxwbP1r');

    const saved = await db.save();
    expect(saved[3]).toBe(0x03);
  });
});

describe('PasswordDatabase.save', () => {
  it('increments the revision and round-trips the data', async () => {
    const db = await loadFixture();
    const reloaded = await PasswordDatabase.load(await db.save(), password);
    expect(reloaded.getRevision()).toBe(3); // 2 -> 3
    expect(reloaded.getAccount('test')).toMatchObject({
      password: 'bYxwbP1r',
      notes: 'test',
    });
    expect(reloaded.getDbOptions().remoteLocation).toBe('');
  });

  it('reproduces test.db byte-for-byte when nothing changed but the revision', async () => {
    const db = await loadFixture();
    db.setRevision(1); // save() increments it back to 2
    expect(toHex(await db.save())).toBe(toHex(dbBytes));
  });
});

describe('PasswordDatabase account management', () => {
  it('adds, gets, deletes and lists names case-insensitively', async () => {
    const db = await loadFixture();
    db.addAccount(new AccountInformation('Zeta'));
    db.addAccount(new AccountInformation('alpha'));
    db.addAccount(new AccountInformation('Beta'));

    expect(db.getAccount('alpha')?.accountName).toBe('alpha');
    expect(db.getAccountNames()).toEqual(['alpha', 'Beta', 'test', 'Zeta']);

    db.deleteAccount('alpha');
    expect(db.getAccount('alpha')).toBeUndefined();
    expect(db.getAccountNames()).toEqual(['Beta', 'test', 'Zeta']);
  });
});

describe('file-less constructor (for the merge)', () => {
  it('starts empty at revision 0 and can be saved', async () => {
    const db = new PasswordDatabase(
      { password, salt: dbBytes.slice(4, 12) },
      new DatabaseOptions(),
    );
    expect(db.getRevision()).toBe(0);
    expect(db.getAccounts()).toHaveLength(0);

    db.addAccount(new AccountInformation('x', 'user', 'secret', '', ''));
    const reloaded = await PasswordDatabase.load(await db.save(), password);
    expect(reloaded.getRevision()).toBe(1);
    expect(reloaded.getAccount('x')?.userId).toBe('user');
  });
});
